css:
.answer-page {
  min-height: 100vh;
  background: #f1f3f8;
  font-family: "Noto Sans SC", "PingFang SC", "Microsoft YaHei", sans-serif;
}
.ap-main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 32px 40px;
}
/* 工具栏 */
.ap-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #ffffff;
  border-radius: 14px;
  padding: 12px 20px;
  box-shadow: 0 2px 12px rgba(26, 43, 95, 0.06);
  margin-bottom: 16px;
  position: sticky;
  top: 80px;
  z-index: 50;
}
.toolbar-left {
  display: flex;
  align-items: center;
  gap: 16px;
}
.tool-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border: 1px solid #e8eaf0;
  border-radius: 10px;
  background: #f8f9fc;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  color: #1a2b5f;
  transition: all 0.3s;
  position: relative;
}
.tool-btn:hover {
  background: #f0f2f5;
}
.tool-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #c41e3a;
  position: absolute;
  top: 6px;
  right: 6px;
}
.progress-text {
  font-size: 14px;
  font-weight: 700;
  color: #1a2b5f;
}
.toolbar-right {
  display: flex;
  align-items: center;
  gap: 16px;
}
.timer-display {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: #f8f9fc;
  border-radius: 10px;
}
.timer-text {
  font-size: 18px;
  font-weight: 900;
  color: #1a2b5f;
  font-family: "SF Mono", "DIN Alternate", "Menlo", monospace;
  letter-spacing: 1px;
}
.timer-text.urgent {
  color: #c41e3a;
  animation: pulse 1s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}
.exit-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 18px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, #c41e3a, #e8384f);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s;
}
.exit-btn:hover {
  transform: scale(1.03);
  box-shadow: 0 2px 10px rgba(196, 30, 58, 0.3);
}
.ap-body {
  display: flex;
  gap: 20px;
  position: relative;
}
/* 答题卡面板 */
.answer-sheet-panel {
  width: 240px;
  flex-shrink: 0;
  background: #ffffff;
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 2px 14px rgba(26, 43, 95, 0.08);
  align-self: flex-start;
  position: sticky;
  top: 160px;
}
.sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.sheet-header h4 {
  font-size: 15px;
  font-weight: 700;
  color: #1a2b5f;
  margin: 0;
}
.sheet-close {
  font-size: 16px;
  color: #8a8faa;
  cursor: pointer;
}
.sheet-stats {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
  font-size: 12px;
  color: #5a6488;
}
.sheet-stats b {
  color: #1a2b5f;
}
.sheet-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin-bottom: 16px;
}
.sheet-num {
  width: 36px;
  height: 36px;
  border: 1px solid #e8eaf0;
  border-radius: 8px;
  background: #f8f9fc;
  font-size: 12px;
  font-weight: 700;
  color: #5a6488;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}
.sheet-num.active {
  border-color: #1a2b5f;
  box-shadow: 0 0 0 2px rgba(26, 43, 95, 0.3);
}
.sheet-num.answered {
  background: #e6f7ec;
  border-color: #22c55e;
  color: #15803d;
}
.sheet-num.marked {
  border-color: #f59e0b;
  background: #fffbeb;
}
.submit-btn {
  width: 100%;
  padding: 10px;
  border: none;
  border-radius: 10px;
  background: linear-gradient(135deg, #1a2b5f, #1e3470);
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.3s;
}
.submit-btn:hover {
  background: linear-gradient(135deg, #c41e3a, #e8384f);
}
.sheet-slide-enter-active, .sheet-slide-leave-active {
  transition: all 0.3s ease;
}
.sheet-slide-enter-from, .sheet-slide-leave-to {
  opacity: 0;
  transform: translateX(-20px);
}
/* 题目区域 */
.question-area {
  flex: 1;
  min-width: 0;
}
.question-scroll {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.question-block {
  background: #ffffff;
  border-radius: 16px;
  padding: 28px;
  box-shadow: 0 2px 14px rgba(26, 43, 95, 0.05);
}
.q-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}
.q-number {
  font-size: 18px;
  font-weight: 900;
  color: #1a2b5f;
}
.q-type-badge {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 8px;
  background: #eff6ff;
  color: #3b82f6;
  font-weight: 600;
}
.mark-badge {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: 8px;
  background: #fffbeb;
  color: #b45309;
  font-weight: 600;
}
.q-stem {
  font-size: 15px;
  line-height: 1.8;
  color: #1a2b5f;
  margin: 0 0 20px;
  font-weight: 500;
}
.q-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.option-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border: 2px solid #e8eaf0;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 14px;
  color: #333;
}
.option-item:hover {
  border-color: #cbd5e0;
  background: #f8f9fc;
}
.option-item.selected {
  border-color: #1a2b5f;
  background: #f0f4ff;
  color: #1a2b5f;
  font-weight: 600;
}
.option-item.correct {
  border-color: #22c55e;
  background: #f0fdf4;
}
.option-item.wrong {
  border-color: #ef4444;
  background: #fef2f2;
}
.option-label {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #f8f9fc;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  flex-shrink: 0;
  color: #5a6488;
}
.option-item.selected .option-label {
  background: #1a2b5f;
  color: #fff;
}
.option-item.correct .option-label {
  background: #22c55e;
  color: #fff;
}
.option-item.wrong .option-label {
  background: #ef4444;
  color: #fff;
}
.q-result {
  margin-top: 16px;
  padding: 12px 16px;
  background: #f8f9fc;
  border-radius: 10px;
}
.result-badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 8px;
}
.result-badge.correct {
  background: #d1fae5;
  color: #065f46;
}
.result-badge.incorrect {
  background: #fee2e2;
  color: #991b1b;
}
.result-explain {
  font-size: 13px;
  color: #5a6488;
  line-height: 1.6;
  margin: 0;
}
.q-actions {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}
.mark-btn {
  padding: 6px 16px;
  border: 1px solid #e8eaf0;
  border-radius: 8px;
  background: #fff;
  font-size: 12px;
  color: #5a6488;
  cursor: pointer;
  transition: all 0.2s;
}
.mark-btn.marked {
  background: #fffbeb;
  border-color: #f59e0b;
  color: #b45309;
}

class.value:
[
  'sheet-num',
  {
    active: this.context.idx === this.state.currentIndex,
    answered: this.state.answers[this.context.q.id] !== undefined,
    marked: this.state.markedQuestions.includes(this.context.q.id)
  }
]
